import java.util.stream.Stream
enum class Status(val code: String) { ACTIVE("A"), INACTIVE("I"), PENDING("P") }
fun fromCode(code: String): Status? = Stream.of(*Status.values()) .filter { it.code == code }.findFirst().orElse(null) // bad: streaming enum on each call

import java.util.Arrays
enum class Color(val hex: String) { RED("#FF0000"), GREEN("#00FF00"), BLUE("#0000FF") }
fun fromHex(hex: String): Color? = Arrays.stream(Color.values()) .filter { it.hex == hex }.findFirst().orElse(null) // bad: re-streaming each time

import java.util.stream.Stream

enum class Priority { LOW, MEDIUM, HIGH }

fun findFirst(codes: List<String>) = codes.map { code ->
    Stream.of(*Priority.values())
        .filter { it.name == code }.findAny().orElse(null) // bad: streaming inside lambda
}

enum class Status(val code: String) {
    ACTIVE("A"), INACTIVE("I"), PENDING("P");
    companion object {
        private val BY_CODE = values().associateBy { it.code } // ok: map built once
        fun fromCode(code: String): Status? = BY_CODE[code]
    }
}
